def build_guarded_refactor_prompt(task: dict[str, Any]) -> str:
    return textwrap.dedent(
        f"""
        <MODE>GUARDED_REFACTOR</MODE>
        <TASK_ID>{task['task_id']}</TASK_ID>
        <FUNCTION>{task['function_name']}</FUNCTION>
        <INSTRUCTION>
        Refactor the Python function while preserving behavior exactly.
        Keep all thresholds, caps, guards, role restrictions, and return values unchanged.
        Prefer helper functions and clearer structure, but do not change semantics.
        {task['instruction']}
        Invariant: {task['invariant_text']}
        </INSTRUCTION>
        <SOURCE_CODE>
        {task['source_code']}
        </SOURCE_CODE>
        <OUTPUT_CODE>
        """
    ).strip() + "\n"

