def build_repair_prompt(task: dict[str, Any], previous_candidate: str, feedback_text: str) -> str:
    return textwrap.dedent(
        f"""
        <MODE>REPAIR</MODE>
        <TASK_ID>{task['task_id']}</TASK_ID>
        <FUNCTION>{task['function_name']}</FUNCTION>
        <INSTRUCTION>
        The previous refactor changed behavior. Keep the refactored structure, but repair the bug.
        Preserve all thresholds, caps, guard conditions, and externally observable outputs.
        {task['instruction']}
        Invariant: {task['invariant_text']}
        </INSTRUCTION>
        <SOURCE_CODE>
        {task['source_code']}
        </SOURCE_CODE>
        <PREVIOUS_CANDIDATE>
        {previous_candidate}
        </PREVIOUS_CANDIDATE>
        <FEEDBACK>
        {feedback_text}
        </FEEDBACK>
        <OUTPUT_CODE>
        """
    ).strip() + "\n"

