def extract_generated_code(text: str) -> str:
    value = text
    if "<OUTPUT_CODE>" in value:
        value = value.split("<OUTPUT_CODE>", 1)[1]
    if "<END>" in value:
        value = value.split("<END>", 1)[0]
    value = value.strip()
    if value.startswith("```"):
        value = value.split("\n", 1)[1] if "\n" in value else value
        if value.endswith("```"):
            value = value[:-3]
    return value.strip() + "\n"

