def find_first_failure(code: str, task: dict[str, Any], suites: list[str]) -> tuple[str, dict[str, Any], Any, Any] | None:
    for suite_name in suites:
        for case in task[suite_name]:
            ok, actual = run_code_on_case(code, task["function_name"], case["input"])
            expected = case["expected"]
            if (not ok) or actual != expected:
                return suite_name, case, actual, expected
    return None

