    rate = rng.choice([0.05, 0.08, 0.10, 0.12])
    cap = rng.choice([20.0, 30.0, 35.0, 40.0])
    fn = _sample_name(rng, "calculate_discount", idx)
    task_id = f"{split}_discount_threshold_{idx}"
    source = f"""
    def {fn}(order):
        customer_type = order["customer_type"]
        total = float(order["total"])
        if customer_type != "vip":
            return 0.0
        if total < {float(threshold)}:
            return 0.0
        raw_discount = total * {rate}
        if raw_discount > {cap}:
            return {cap}
        return raw_discount
    """
    correct = f"""
    def _is_discount_eligible(order):
        return order["customer_type"] == "vip" and float(order["total"]) >= {float(threshold)}

    def _raw_discount(order):
        return float(order["total"]) * {rate}

    def {fn}(order):
        if not _is_discount_eligible(order):
            return 0.0
        return min(_raw_discount(order), {cap})
    """
    buggy = f"""
    def _is_discount_eligible(order):
        return order["customer_type"] == "vip" and float(order["total"]) > {float(threshold)}

    def _raw_discount(order):
        return float(order["total"]) * {rate}

    def {fn}(order):
        if not _is_discount_eligible(order):
            return 0.0
        return min(_raw_discount(order), {cap})
    """
    return Task(
        task_id=task_id,
        split=split,
        family="hidden_boundary",
        function_name=fn,
        instruction="Extract helpers for discount eligibility and computation.",
        invariant_text=f"VIP orders at total = {float(threshold)} must still receive the inclusive discount.",
        source_code=normalize_code(source),
        correct_code=normalize_code(correct),
        buggy_code=normalize_code(buggy),
        public_cases=[
            {
                "input": {"customer_type": "regular", "total": threshold + 10},
                "expected": 0.0,
                "property": "Regular customers must never receive the VIP discount.",
            },
            {
                "input": {"customer_type": "vip", "total": threshold + 10},
                "expected": min((threshold + 10) * rate, cap),
                "property": "VIP orders above the threshold must receive the configured percentage discount.",
            },
            {
                "input": {"customer_type": "vip", "total": threshold + 20},
                "expected": min((threshold + 20) * rate, cap),
                "property": "VIP orders above the threshold must receive the configured percentage discount.",
            },
        ],
        guard_cases=[
            {
                "input": {"customer_type": "vip", "total": float(threshold)},
                "expected": min(threshold * rate, cap),
                "property": f"VIP orders at total = {float(threshold)} must still receive the inclusive discount.",
            },
        ],
        oracle_cases=[
            {
                "input": {"customer_type": "regular", "total": threshold + 10},
                "expected": 0.0,
                "property": "Regular customers must never receive the VIP discount.",
            },
            {
                "input": {"customer_type": "vip", "total": threshold - 0.01},
                "expected": 0.0,
                "property": "VIP orders below the threshold must not receive the discount.",
            },
            {
                "input": {"customer_type": "vip", "total": float(threshold)},
                "expected": min(threshold * rate, cap),
                "property": f"VIP orders at total = {float(threshold)} must still receive the inclusive discount.",
            },
            {
                "input": {"customer_type": "vip", "total": threshold + 10},
                "expected": min((threshold + 10) * rate, cap),
                "property": "VIP orders above the threshold must receive the configured percentage discount.",
            },
            {
                "input": {"customer_type": "vip", "total": threshold + 20},
                "expected": min((threshold + 20) * rate, cap),
                "property": "VIP orders above the threshold must receive the configured percentage discount.",
            },
        ],
    )

