    threshold = rng.choice([30, 40, 50, 60, 80])
    country = rng.choice(["RU", "KZ", "BY"])
    fee = rng.choice([5.0, 7.5, 10.0])
    fn = _sample_name(rng, "shipping_fee", idx)
    source = f"""
    def {fn}(order):
        subtotal = float(order["subtotal"])
        country = order["country"]
        if country != "{country}":
            return {fee}
        if subtotal < {float(threshold)}:
            return {fee}
        return 0.0
    """
    correct = f"""
    def _free_shipping_applies(order):
        return order["country"] == "{country}" and float(order["subtotal"]) >= {float(threshold)}

    def {fn}(order):
        return 0.0 if _free_shipping_applies(order) else {fee}
    """
    buggy = f"""
    def _free_shipping_applies(order):
        return order["country"] == "{country}" and float(order["subtotal"]) > {float(threshold)}

    def {fn}(order):
        return 0.0 if _free_shipping_applies(order) else {fee}
    """
    return Task(
        task_id=f"{split}_free_shipping_{idx}",
        split=split,
        family="hidden_boundary",
        function_name=fn,
        instruction="Extract the shipping eligibility logic into a helper function.",
        invariant_text=f"Orders from {country} at subtotal = {float(threshold)} must still receive free shipping.",
        source_code=normalize_code(source),
        correct_code=normalize_code(correct),
        buggy_code=normalize_code(buggy),
        public_cases=[
            {"input": {"country": country, "subtotal": threshold - 1}, "expected": fee, "property": "Orders below the threshold must keep the shipping fee."},
            {"input": {"country": country, "subtotal": threshold + 20}, "expected": 0.0, "property": "Orders above the threshold must receive free shipping."},
            {"input": {"country": "US", "subtotal": threshold + 20}, "expected": fee, "property": "Orders from another country must keep the shipping fee."},
        ],
        guard_cases=[{"input": {"country": country, "subtotal": float(threshold)}, "expected": 0.0, "property": f"Orders from {country} at subtotal = {float(threshold)} must still receive free shipping."}],
        oracle_cases=[
            {"input": {"country": country, "subtotal": threshold - 1}, "expected": fee, "property": "Orders below the threshold must keep the shipping fee."},
            {"input": {"country": country, "subtotal": float(threshold)}, "expected": 0.0, "property": f"Orders from {country} at subtotal = {float(threshold)} must still receive free shipping."},
            {"input": {"country": country, "subtotal": threshold + 20}, "expected": 0.0, "property": "Orders above the threshold must receive free shipping."},
            {"input": {"country": "US", "subtotal": threshold + 20}, "expected": fee, "property": "Orders from another country must keep the shipping fee."},
        ],
    )

