def make_discount_cap_task(rng: random.Random, split: str, idx: int) -> Task:
    threshold = rng.choice([80, 100, 120])
    rate = rng.choice([0.10, 0.12, 0.15])
    cap = rng.choice([20.0, 25.0, 30.0])
    wrong_cap = cap - 5.0
    fn = _sample_name(rng, "capped_discount", idx)
    source = f"""
    def {fn}(order):
        if order["customer_type"] != "vip":
            return 0.0
        total = float(order["total"])
        if total < {float(threshold)}:
            return 0.0
        raw = total * {rate}
        return {cap} if raw > {cap} else raw
    """
    correct = f"""
    def _eligible(order):
        return order["customer_type"] == "vip" and float(order["total"]) >= {float(threshold)}

    def _discount_value(order):
        return float(order["total"]) * {rate}

    def {fn}(order):
        if not _eligible(order):
            return 0.0
        return min(_discount_value(order), {cap})
    """
    buggy = f"""
    def _eligible(order):
        return order["customer_type"] == "vip" and float(order["total"]) >= {float(threshold)}

    def _discount_value(order):
        return float(order["total"]) * {rate}

    def {fn}(order):
        if not _eligible(order):
            return 0.0
        return min(_discount_value(order), {wrong_cap})
    """
    return Task(
        task_id=f"{split}_discount_cap_{idx}",
        split=split,
        family="visible_regression",
        function_name=fn,
        instruction="Refactor the cap logic into helpers without changing the maximum discount.",
        invariant_text=f"The maximum discount cap must remain {cap}.",
        source_code=normalize_code(source),
        correct_code=normalize_code(correct),
        buggy_code=normalize_code(buggy),
