def make_guard_task(rng: random.Random, split: str, idx: int) -> Task:
    threshold = rng.choice([75, 100, 120])
    fn = _sample_name(rng, "vip_flat_discount", idx)
    source = f"""
    def {fn}(order):
        customer_type = order["customer_type"]
        total = float(order["total"])
        if customer_type != "vip":
            return 0.0
        if total < {float(threshold)}:
            return 0.0
        return 10.0
    """
    correct = f"""
    def _eligible(order):
        return order["customer_type"] == "vip" and float(order["total"]) >= {float(threshold)}

    def {fn}(order):
        return 10.0 if _eligible(order) else 0.0
    """
    buggy = f"""
    def _eligible(order):
        return float(order["total"]) >= {float(threshold)}

    def {fn}(order):
        return 10.0 if _eligible(order) else 0.0
    """
    return Task(
        task_id=f"{split}_vip_guard_{idx}",
        split=split,
        family="visible_regression",
        function_name=fn,
        instruction="Extract the eligibility guard without changing who may receive the discount.",
        invariant_text="Regular customers must never receive the VIP-only discount.",
        source_code=normalize_code(source),
        correct_code=normalize_code(correct),
        buggy_code=normalize_code(buggy),
        public_cases=[
            {"input": {"customer_type": "regular", "total": threshold + 50}, "expected": 0.0, "property": "Regular customers must never receive the VIP-only discount."},
            {"input": {"customer_type": "vip", "total": threshold + 50}, "expected": 10.0, "property": "Eligible VIP customers must still receive the flat discount."},
        ],
        guard_cases=[{"input": {"customer_type": "regular", "total": threshold + 50}, "expected": 0.0, "property": "Regular customers must never receive the VIP-only discount."}],
        oracle_cases=[
            {"input": {"customer_type": "regular", "total": threshold + 50}, "expected": 0.0, "property": "Regular customers must never receive the VIP-only discount."},
            {"input": {"customer_type": "vip", "total": threshold - 1}, "expected": 0.0, "property": "VIP customers below the threshold must not receive the discount."},
            {"input": {"customer_type": "vip", "total": threshold + 50}, "expected": 10.0, "property": "Eligible VIP customers must still receive the flat discount."},
        ],
    )

