def make_undercovered_expedite_task(rng: random.Random, split: str, idx: int) -> Task:
    threshold = rng.choice([150, 180, 200, 250])
    fee = rng.choice([10.0, 15.0, 20.0])
    fn = _sample_name(rng, "expedite_fee", idx)
    source = f"""
    def {fn}(order):
        expedited = bool(order["expedited"])
        subtotal = float(order["subtotal"])
        if not expedited:
            return 0.0
        if subtotal < {float(threshold)}:
            return {fee}
        return 0.0
    """
    correct = f"""
    def _free_expedite(order):
        return bool(order["expedited"]) and float(order["subtotal"]) >= {float(threshold)}

    def {fn}(order):
        if not bool(order["expedited"]):
            return 0.0
        return 0.0 if _free_expedite(order) else {fee}
    """
    buggy = f"""
    def _free_expedite(order):
        return bool(order["expedited"]) and float(order["subtotal"]) > {float(threshold)}

    def {fn}(order):
        if not bool(order["expedited"]):
            return 0.0
        return 0.0 if _free_expedite(order) else {fee}
    """
    return Task(
        task_id=f"{split}_undercovered_expedite_{idx}",
        split=split,
        family="undercovered_hidden_bug",
        function_name=fn,
        instruction="Refactor the expedited shipping rule into helpers.",
        invariant_text=f"Expedited orders at subtotal = {float(threshold)} must keep the original threshold behavior.",
        source_code=normalize_code(source),
        correct_code=normalize_code(correct),
        buggy_code=normalize_code(buggy),
        public_cases=[
            {"input": {"expedited": False, "subtotal": threshold + 20}, "expected": 0.0, "property": "Non-expedited orders must stay free of expedite fees."},
            {"input": {"expedited": True, "subtotal": threshold + 20}, "expected": 0.0, "property": "Orders above the threshold must keep free expedited shipping."},
            {"input": {"expedited": True, "subtotal": threshold - 5}, "expected": fee, "property": "Orders below the threshold must keep the expedite fee."},
        ],
        guard_cases=[],
        oracle_cases=[
            {"input": {"expedited": False, "subtotal": threshold + 20}, "expected": 0.0, "property": "Non-expedited orders must stay free of expedite fees."},
            {"input": {"expedited": True, "subtotal": threshold - 5}, "expected": fee, "property": "Orders below the threshold must keep the expedite fee."},
            {"input": {"expedited": True, "subtotal": float(threshold)}, "expected": 0.0, "property": f"Expedited orders at subtotal = {float(threshold)} must keep the original threshold behavior."},
            {"input": {"expedited": True, "subtotal": threshold + 20}, "expected": 0.0, "property": "Orders above the threshold must keep free expedited shipping."},
        ],
    )

