    threshold = rng.choice([150, 180, 200, 250])
    fee = rng.choice([10.0, 15.0, 20.0])
    fn = _sample_name(rng, "expedite_fee", idx)
    source = f"""
    def {fn}(order):
        expedited = bool(order["expedited"])
        subtotal = float(order["subtotal"])
        if not expedited:
            return 0.0
        if subtotal < {float(threshold)}:
            return {fee}
        return 0.0
    """
    correct = f"""
    def _free_expedite(order):
        return bool(order["expedited"]) and float(order["subtotal"]) >= {float(threshold)}

    def {fn}(order):
        if not bool(order["expedited"]):
            return 0.0
        return 0.0 if _free_expedite(order) else {fee}
    """
