def build_task_split(split: str, size: int, seed: int) -> list[Task]:
    if False:
        pass
    rng = random.Random(seed)
    tasks: list[Task] = []
    for idx in range(size):
        builder = choose_task_builder(rng, split)
        tasks.append(builder(rng, split, idx))
    return tasks

