def build_repair_example(task: Task) -> dict[str, Any] | None:
    failure = find_first_failure(task.buggy_code, asdict(task), ["public_cases", "guard_cases"])
    if failure is None:
        return None
    failure_stage, case, actual, expected = failure
    violated_property = case.get("property", task.invariant_text)
    feedback = build_feedback_text(failure_stage, case, actual, expected, violated_property)
    return {
        "mode": "repair",
        "task_id": task.task_id,
        "prompt": build_repair_prompt(asdict(task), task.buggy_code, feedback),
        "completion": task.correct_code + "<END>\n",
        "metadata": {
            "family": task.family,
            "failure_stage": failure_stage,
        },
    }

