def build_sft_records(tasks: list[Task]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for task in tasks:
        rows.append(
            {
                "mode": "ordinary_refactor",
                "task_id": task.task_id,
                "prompt": build_ordinary_refactor_prompt(asdict(task)),
                "completion": task.correct_code + "<END>\n",
                "metadata": {"family": task.family},
            }
        )
        rows.append(
            {
                "mode": "guarded_refactor",
                "task_id": task.task_id,
                "prompt": build_guarded_refactor_prompt(asdict(task)),
                "completion": task.correct_code + "<END>\n",
                "metadata": {"family": task.family},
            }
        )
        repair = build_repair_example(task)
        if repair is not None:
            rows.append(repair)
    return rows

