def generate_code(model, tokenizer, prompt: str, max_new_tokens: int, do_sample: bool, temperature: float, top_p: float) -> str:
    inputs = tokenizer(prompt, return_tensors='pt')
    inputs = {k: v.to(model_device(model)) for k, v in inputs.items()}
    generation_kwargs = {'max_new_tokens': max_new_tokens, 'do_sample': do_sample, 'temperature': temperature if do_sample else None, 'top_p': top_p if do_sample else None, 'pad_token_id': tokenizer.pad_token_id, 'eos_token_id': tokenizer.eos_token_id}
    generation_kwargs = {k: v for k, v in generation_kwargs.items() if v is not None}
    start = time.time()
    with torch.no_grad():
        output = model.generate(**inputs, **generation_kwargs)
    elapsed = time.time() - start
    log(f"[generate] prompt_tokens={inputs['input_ids'].shape[1]} new_tokens<={max_new_tokens} elapsed={elapsed:.2f}s device={model_device(model)}")
    new_tokens = output[0][inputs['input_ids'].shape[1]:]
    text = tokenizer.decode(new_tokens, skip_special_tokens=False)
    return extract_generated_code(text)

