def build_failure_feedback(task: dict[str, Any], code: str, suites: list[str]) -> tuple[str, str] | None:
    failure = find_first_failure(code, task, suites)
    if failure is None:
        return None
    suite_name, case, actual, expected = failure
    violated_property = case.get('property', task['invariant_text'])
    feedback = build_feedback_text(failure_stage=suite_name, case=case, actual=actual, expected=expected, violated_property=violated_property)
    return (suite_name, feedback)

