def run_baseline(model, tokenizer, task: dict[str, Any], max_new_tokens: int, do_sample: bool, temperature: float, top_p: float) -> TaskResult:
    if False:
        pass
    prompt = build_ordinary_refactor_prompt(task)
    code = generate_code(model, tokenizer, prompt, max_new_tokens, do_sample, temperature, top_p)
    is_syntax_ok = syntax_ok(code, task['function_name'], task)
    public_pass = is_syntax_ok and evaluate_suite(code, task, 'public_cases')
    guard_pass = is_syntax_ok and evaluate_suite(code, task, 'guard_cases')
    oracle_pass = is_syntax_ok and evaluate_suite(code, task, 'oracle_cases')
    return TaskResult(strategy='ordinary_refactoring', task_id=task['task_id'], family=task['family'], syntax_ok=is_syntax_ok, accepted=is_syntax_ok, public_pass=public_pass, guard_pass=guard_pass, oracle_pass=oracle_pass, iterations=1, generated_code=code, final_feedback='')

def run_refactorguard(model, tokenizer, task: dict[str, Any], max_new_tokens: int, do_sample: bool, temperature: float, top_p: float, max_iterations: int) -> TaskResult:
    if False:
        pass
    prompt = build_guarded_refactor_prompt(task)
    code = generate_code(model, tokenizer, prompt, max_new_tokens, do_sample, temperature, top_p)
    feedback_log = []
    for iteration in range(1, max_iterations + 1):
        is_syntax_ok = syntax_ok(code, task['function_name'], task)
        if not is_syntax_ok:
            feedback = 'failure_stage = syntax\nviolated_property = generated code must be valid Python'
            feedback_log.append(feedback)
        else:
            failed = build_failure_feedback(task, code, ['public_cases', 'guard_cases'])
            if failed is None:
                public_pass = evaluate_suite(code, task, 'public_cases')
                guard_pass = evaluate_suite(code, task, 'guard_cases')
                oracle_pass = evaluate_suite(code, task, 'oracle_cases')
                return TaskResult(strategy='refactorguard_sc', task_id=task['task_id'], family=task['family'], syntax_ok=True, accepted=True, public_pass=public_pass, guard_pass=guard_pass, oracle_pass=oracle_pass, iterations=iteration, generated_code=code, final_feedback='\n---\n'.join(feedback_log))
            _, feedback = failed
            feedback_log.append(feedback)
        if iteration == max_iterations:
            break
        repair_prompt = build_repair_prompt(task, code, feedback_log[-1])
        code = generate_code(model, tokenizer, repair_prompt, max_new_tokens, do_sample, temperature, top_p)
    final_syntax = syntax_ok(code, task['function_name'], task)
    public_pass = final_syntax and evaluate_suite(code, task, 'public_cases')
    guard_pass = final_syntax and evaluate_suite(code, task, 'guard_cases')
    oracle_pass = final_syntax and evaluate_suite(code, task, 'oracle_cases')
    return TaskResult(strategy='refactorguard_sc', task_id=task['task_id'], family=task['family'], syntax_ok=final_syntax, accepted=False, public_pass=public_pass, guard_pass=guard_pass, oracle_pass=oracle_pass, iterations=max_iterations, generated_code=code, final_feedback='\n---\n'.join(feedback_log))

def aggregate(results: list[TaskResult]) -> list[dict[str, Any]]:
    grouped: dict[str, list[TaskResult]] = {}
    for result in results:
        grouped.setdefault(result.strategy, []).append(result)
    summary: list[dict[str, Any]] = []
    for strategy, items in grouped.items():
        total = len(items)
        syntax = sum((1 for x in items if x.syntax_ok))
        accepted = sum((1 for x in items if x.accepted))
        public_pass = sum((1 for x in items if x.public_pass))
        guard_pass = sum((1 for x in items if x.guard_pass))
        oracle_pass = sum((1 for x in items if x.oracle_pass))
        hallucinations = total - oracle_pass
        summary.append({'strategy': strategy, 'total_tasks': total, 'syntax_valid_rate': round(100.0 * syntax / total, 2), 'accepted_rate': round(100.0 * accepted / total, 2), 'public_test_pass_rate': round(100.0 * public_pass / total, 2), 'guard_pass_rate': round(100.0 * guard_pass / total, 2), 'semantic_preservation_rate': round(100.0 * oracle_pass / total, 2), 'hallucination_rate': round(100.0 * hallucinations / total, 2), 'mean_iterations': round(mean([x.iterations for x in items]), 2)})
    return sorted(summary, key=lambda x: x['strategy'])

