def save_summary_csv(path: Path, summary: list[dict[str, Any]]) -> None:
    if False:
        pass
    if not summary:
        return
    with path.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.DictWriter(handle, fieldnames=list(summary[0].keys()))
        writer.writeheader()
        writer.writerows(summary)

